        </div>

        <div class="form-group">
            <label for="char-name">角色名</label>
            <input type="text" id="char-name" placeholder="输入你的名字...">
        </div>

        <div class="form-group">
            <label>性别</label>
            <div class="gender-selector">
                <div class="gender-option" data-value="男">男</div>
                <div class="gender-option" data-value="扶她">扶她</div>
            </div>
        </div>

        <div class="form-group">
            <label for="char-age">年龄</label>
            <input type="number" id="char-age" placeholder="输入年龄...">
        </div>

        <div class="form-group">
            <label for="char-personality">性格</label>
            <textarea id="char-personality" placeholder="描述你的性格..."></textarea>
        </div>

        <div class="form-group">
            <label for="char-appearance">外貌</label>
            <textarea id="char-appearance" placeholder="描述你的外貌..."></textarea>
        </div>

        <button id="create-btn">创建角色</button>
    </div>

    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const genderOptions = document.querySelectorAll('.gender-option');
        let selectedGender = '';

        genderOptions.forEach(option => {
            option.addEventListener('click', () => {
                genderOptions.forEach(opt => opt.classList.remove('selected'));
                option.classList.add('selected');
                selectedGender = option.getAttribute('data-value');
            });
        });

        document.getElementById('create-btn').addEventListener('click', () => {
            const charName = document.getElementById('char-name').value;
            const charAge = document.getElementById('char-age').value;
            const charPersonality = document.getElementById('char-personality').value;
            const charAppearance = document.getElementById('char-appearance').value;

            if (!charName || !selectedGender || !charAge || !charPersonality || !charAppearance) {
                alert('请填写所有字段！');
                return;
            }

            // 【修改开始】
            // 1. 准备用于发送的原始格式文本
            const characterInfoText = `<用户角色档案>
名字：${charName}
性别：${selectedGender}
年龄：${charAge}
性格：${charPersonality}
外貌：${charAppearance}
</用户角色档案>`;

            // 2. 构建一个STscript命令链，用于设置变量
            // 为了防止特殊字符破坏命令，将文本编码为Base64
            const personalityBase64 = btoa(unescape(encodeURIComponent(charPersonality)));
            const appearanceBase64 = btoa(unescape(encodeURIComponent(charAppearance)));

            const commandChain = [
                `/setvar key=createdChar_name value="${charName}"`,
                `/setvar key=createdChar_gender value="${selectedGender}"`,
                `/setvar key=createdChar_age value="${charAge}"`,
                // 使用Base64编码存储可能包含换行符和特殊字符的字段
                `/setvar key=createdChar_personality_b64 value="${personalityBase64}"`,
                `/setvar key=createdChar_appearance_b64 value="${appearanceBase64}"`,
                // 3. 将原始格式文本作为用户消息发送，并触发AI生成
                `/send ${characterInfoText} | /trigger`
            ].join(' | ');
            // 【修改结束】


            if (typeof triggerSlash === 'function') {
                // 执行构建好的命令链
                triggerSlash(commandChain);
            } else {
                console.error('triggerSlash function not found. Are you in SillyTavern?');
                alert('角色信息已生成，请手动复制粘贴。\n\n' + characterInfoText);
                console.log('Would execute command:', commandChain);
            }
        });
    });
</script>
</body>
</html>
