    <script>
        // --- 游戏状态变量 ---
        let conquestPoints = parseInt($8) || 0;
        const lotteryCost = parseInt($14) || 0;

        // --- DOM元素获取 ---
        const conquestPointsDisplay = document.getElementById('conquest-points-display');
        const lotteryBtn = document.getElementById('lottery-btn');
        const resultDisplay = document.getElementById('result-display');

        // --- 抽奖逻辑 ---
        const rewards = [
            { name: '普通', color: 'white', probability: 0.30 },
            { name: '一般', color: 'green', probability: 0.25 },
            { name: '精品', color: 'blue', probability: 0.20 },
            { name: '极品', color: 'yellow', probability: 0.15 },
            { name: '至尊', color: 'red', probability: 0.10 }
        ];

        function checkPointsAndUpdateButton() {
            lotteryBtn.disabled = conquestPoints < lotteryCost;
        }

        lotteryBtn.addEventListener('click', () => {
            if (conquestPoints < lotteryCost) return;

            // 更新本地UI状态
            conquestPoints -= lotteryCost;
            conquestPointsDisplay.textContent = conquestPoints;
            checkPointsAndUpdateButton();

            lotteryBtn.disabled = true;
            lotteryBtn.textContent = '抽取中...';
            resultDisplay.textContent = '';
            resultDisplay.className = '';

            setTimeout(() => {
                const rand = Math.random();
                let cumulativeProbability = 0;
                let chosenReward = rewards[rewards.length - 1];

                for (const reward of rewards) {
                    cumulativeProbability += reward.probability;
                    if (rand < cumulativeProbability) {
                        chosenReward = reward;
                        break;
                    }
                }

                resultDisplay.textContent = `恭喜！抽中【${chosenReward.name}】礼盒！`;
                resultDisplay.classList.add(`result-${chosenReward.color}`);

                // 【修改开始 - 抽奖】
                const messageToSend = `💓抽奖结果：${chosenReward.name}礼盒💓<!--除初始抽奖外需扣除1000征服点-->`;

                const commandChain = [
                    // 假设征服点变量名为 "conquest_points"，这里用 addvar 来减去消耗值
                    `/addvar key=conquest_points increment=-${lotteryCost}`,
                    // 将本次抽奖结果存入变量
                    `/setvar key=lottery_lastResult value=${chosenReward.name}`,
                    // 发送消息并触发
                    `/send ${JSON.stringify(messageToSend)} | /trigger`
                ].join(' | ');

                if (typeof triggerSlash === 'function') {
                    triggerSlash(commandChain);
                } else {
                    console.error('triggerSlash not found.');
                    alert(messageToSend);
                    console.log('Would execute command:', commandChain);
                }
                // 【修改结束 - 抽奖】

                lotteryBtn.textContent = '再次抽取';
                checkPointsAndUpdateButton();

            }, 1500);
        });

        // --- 通用函数 ---
        function setupAccordion(selector, parentPanelSelector = null) {
            document.querySelectorAll(selector).forEach(acc => {
                const header = acc.querySelector('.accordion-header, .sub-accordion-header');
                const panel = acc.querySelector('.accordion-panel, .sub-accordion-panel');

                if (!header || !panel) return;

                header.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const isActive = acc.classList.contains('active');
                    if (isActive) {
                        closeAccordion(acc, panel);
                    } else {
                        openAccordion(acc, panel);
                    }
                    if(parentPanelSelector){
                        const parentAccordion = acc.closest(parentPanelSelector);
                        if(parentAccordion && parentAccordion.classList.contains('active')){
                           const parentPanel = parentAccordion.querySelector('.accordion-panel');
                           setTimeout(() => {
                               if (parentAccordion.classList.contains('active')) {
                                   parentPanel.style.maxHeight = parentPanel.scrollHeight + "px";
                               }
                           }, 400);
                        }
                    }
                });
            });
        }

        function openAccordion(accordion, panel) {
            accordion.classList.add('active');
            panel.style.maxHeight = panel.scrollHeight + "px";
        }

        function closeAccordion(accordion, panel) {
            accordion.classList.remove('active');
            panel.style.maxHeight = '0px';
        }

        document.querySelectorAll('.choice-button').forEach(button => {
            button.addEventListener('click', () => {
                const choiceText = button.getAttribute('data-choice');
                if (!choiceText) return;

                // 【修改开始 - 选择】
                const commandChain = [
                    // 将用户的选择存入变量
                    `/setvar key=user_lastChoice value="${choiceText}"`,
                    // 发送消息并触发
                    `/send ${JSON.stringify(choiceText)} | /trigger`
                ].join(' | ');

                if (typeof triggerSlash === 'function') {
                    triggerSlash(commandChain);
                } else {
                    console.error('triggerSlash not found.');
                    alert('你的选择是: ' + choiceText);
                    console.log('Would execute command:', commandChain);
                }
                // 【修改结束 - 选择】
            });
        });

        // --- 初始化 ---
        document.addEventListener('DOMContentLoaded', () => {
            setupAccordion('.accordion');
            setupAccordion('.sub-accordion', '.accordion');

            document.querySelectorAll('.accordion.active').forEach(acc => {
                 const panel = acc.querySelector('.accordion-panel');
                 if(panel) {
                    setTimeout(() => openAccordion(acc, panel), 10);
                 }
            });

            conquestPointsDisplay.textContent = conquestPoints;
            checkPointsAndUpdateButton();
        });
    </script>
</body>
</html>
