            font-size: 1.1em; color: var(--primary-purple); text-shadow: 0 0 4px var(--primary-purple);
            margin: 0 auto 20px auto; animation: text-flicker 3s infinite;
        }
        @keyframes text-flicker { 0%, 100% { opacity: 1; } 50% { opacity: 0.7; } }
        @keyframes glitch {
            0%, 100% { transform: translate(0, 0); } 10% { transform: translate(-3px, 3px); } 20% { transform: translate(3px, -3px); }
            30% { transform: translate(-3px, -3px); } 40% { transform: translate(3px, 3px); }
            50% { clip-path: polygon(10% 15%, 30% 0%, 60% 20%, 90% 0%, 100% 35%, 80% 60%, 100% 90%, 65% 100%, 40% 80%, 15% 100%, 0% 70%, 10% 40%); }
            60% { transform: translate(0, 0); }
        }
        @keyframes border-flicker { 0%, 100% { opacity: 0.8; } 50% { opacity: 0.4; } }
